Data.Script:
var ids = [];
try { ids = JSON.parse(vars.ft_raw || "[]"); } catch (e) { ids = []; }
var byId = {};
(vars.ft_all || []).forEach(function (e) { byId[String(e.Id)] = e; });
var targets = [];
ids.forEach(function (id) {
  var e = byId[id];
  if (!e) return;
  var o = {};
  try { o = JSON.parse(e.Object || "{}"); } catch (x) {}
  targets.push({ id: id, name: o.name || "token" });
});
var names = targets.map(function (t) { return t.name; }).join(", ");
var none = targets.length === 0;
return {
  ft_targets: targets,
  ft_text: none ? "No targets marked: use the Mark targets tool first." : vars.playerName + ": Bless on " + names,
  ft_to: none ? vars.playerId : ""
};
